rowdata.pyStepsJavaSource:
hasBlob = false;
String clName = tools.getPrimaryPage().getString("pxObjClass");
try {
  hasBlob = tools.getDatabase().getClassDef(clName).getTable().hasStream();
} catch (Exception e) {
  // if something goes wrong assume that it is mapped to a blob
  return true;
}

boolean autoPopulateDisabledStatus = tools.getThread().getDisableAutoPopulate();
try {
  tools.getThread().setDisableAutoPopulate(true);
  Boolean skipHistoryOverride = null; // If this value stays null, let the engine decide how to save history
  try{
    if(tools.getParameterPage().getAsBoolean("SkipHistory")){
      skipHistoryOverride = true; // Force skip history if parameter set
    } else {
      PegaClassDefinition classInstance = (PegaClassDefinition)tools.getDatabase().getClassDef(myStepPage.getClassName());
      if(classInstance.getAllAncestorClasses().contains("Data-") && classInstance.isSkipHistorySnapshotSettingBlank()){
        skipHistoryOverride = false; // Force save history if Data- and no skip history value (maintains behavior from 8.2)
      }
    }
  } catch(Exception e){
    oLog.error("Unable to determine history behavior", e);
  }
  ((PegaDatabase)tools.getDatabase()).saveDeferred(myStepPage, false, true, false, skipHistoryOverride);

} catch (BadInputException bie) {
  if (oLog.isDebugEnabled()){
    oLog.debug("Save failed due to an invalid page.", bie);
  }
} catch (PRException pre) {
  oLog.error("Save failed.", pre);
} finally {
  tools.getThread().setDisableAutoPopulate(autoPopulateDisabledStatus);
}

if (myStepPage == null) 
{

}
 else if (myStepPage.isEmbedded())
{
    myStepPage = myStepPage.getTopLevelPage();
}

String strMessage = tools.getActivityStatus().getWorstMessage();
if (!tools.getPrimaryPage().hasMessages()){
tools.getPrimaryPage().addMessage("pySaveFailed\t" + strMessage);
}

// If the save failed and this is a new record, we want to keep thinking
// it is a new record by removing the pxUpdateOperator.
// If it is not a new record, then so what?  The pxUpdateOperator will be set
ClipboardProperty updateOperator = tools.getPrimaryPage().getProperty(".pxUpdateOperator");
updateOperator.setValue("");

// local parameter bNewRecord will tell us whether this is a new record

if (bNewRecord)
{
	tools.getPrimaryPage().getProperty(".pzInsKey").setValue("");
}

try
{
	tools.getDatabase().rollback();
} 
catch (DatabaseException e)
{
	tools.getPrimaryPage().addMessage("Rollback failed. Log off and on to ensure no records are erroneously saved or deleted.\n" + e.getMessage());
}
